-- Itemized precious metals collection: each row is one lot of a specific
-- coin/bar/round (e.g. "20x 2016 American Silver Eagle"), matching how the
-- user actually tracks their collection. Distinct from, but feeds, the
-- lump-sum "Precious Metals" manual account (metal_troy_oz on `account`,
-- added in 0009) that drives net worth -- syncMetalCollectionAccounts (see
-- src/lib/metal-items.ts) keeps that account's metal_troy_oz in sync with
-- the sum of metal_item rows below (finding the existing gold/silver
-- account if the user already added one, or creating it) instead of it
-- being hand-edited via "Update ounces".
CREATE TABLE metal_item (
  id TEXT PRIMARY KEY,
  metal TEXT NOT NULL, -- gold | silver
  category TEXT NOT NULL, -- bullion_coin | bullion_bar_round | junk_silver | numismatic | other
  name TEXT NOT NULL, -- e.g. "American Silver Eagle"
  mint TEXT, -- issuing mint/country or private refiner, e.g. "US", "CAN", "Engelhard"
  year INTEGER, -- nullable -- many junk-silver/generic lots have no single mint year
  condition TEXT, -- e.g. "Uncirculated", "Proof", "Cull", "MS61 (NGC)"
  quantity REAL NOT NULL DEFAULT 1, -- count of individual coins/bars in this lot
  troy_oz_each REAL NOT NULL, -- troy oz per single unit (e.g. 1 for a 1oz coin, 0.715 for $1 face of 90% silver)
  face_value_each REAL, -- legal-tender face value per unit, if any (e.g. $1 for an ASE)
  purchase_price_total REAL, -- total $ paid for this lot, if known
  purchase_date TEXT, -- ISO date, if known
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_metal_item_metal ON metal_item (metal);

